SELECT * FROM pos_recharge
WHERE deleted = 0

    AND customer_id = #{customerId}


    AND recharge_type = #{rechargeType}


    AND pay_type = #{payType}


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT * FROM pos_recharge
WHERE deleted = 0 AND customer_id = #{customerId}
ORDER BY create_time DESC

SELECT * FROM pos_recharge
WHERE deleted = 0
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}
ORDER BY create_time DESC

SELECT COALESCE(SUM(recharge_amount), 0) FROM pos_recharge
WHERE deleted = 0
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}

SELECT COALESCE(SUM(gift_amount), 0) FROM pos_recharge
WHERE deleted = 0
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}

SELECT COUNT(*) FROM pos_recharge
WHERE deleted = 0
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}
